assert totals([])=={}
assert totals([{'category':'x','amount_cents':10**40}])=={'x':10**40}
for bad in (None,{},'',(),[None],[1],[{}],[{'category':'x'}],[{'amount_cents':1}],[{'category':'','amount_cents':1}],[{'category':1,'amount_cents':1}],[{'category':'x','amount_cents':True}],[{'category':'x','amount_cents':False}],[{'category':'x','amount_cents':1.0}],[{'category':'x','amount_cents':'1'}]):
 try: totals(bad)
 except ValueError: pass
 else: raise AssertionError(repr(bad))
